import java.io.*;
import java.util.*;

public class Main {
    static int[] dist, heap, pos;
    static int heapSize;

    static void pushOrDecrease(int node) {
        int i = pos[node];
        if (i == -1) {
            i = heapSize++;
            heap[i] = node;
            pos[node] = i;
        }
        while (i > 0) {
            int p = (i - 1) >>> 1;
            if (dist[heap[p]] <= dist[node]) break;
            heap[i] = heap[p];
            pos[heap[i]] = i;
            i = p;
        }
        heap[i] = node;
        pos[node] = i;
    }

    static int pop() {
        int result = heap[0];
        pos[result] = -2;
        int last = heap[--heapSize];
        if (heapSize > 0) {
            int i = 0;
            while (true) {
                int left = i * 2 + 1;
                if (left >= heapSize) break;
                int right = left + 1;
                int child = right < heapSize && dist[heap[right]] < dist[heap[left]]
                        ? right : left;
                if (dist[last] <= dist[heap[child]]) break;
                heap[i] = heap[child];
                pos[heap[i]] = i;
                i = child;
            }
            heap[i] = last;
            pos[last] = i;
        }
        return result;
    }

    static void relax(int node, int cost, int currentDistance) {
        if (pos[node] == -2) return;
        int candidate = currentDistance + cost;
        if (candidate < dist[node]) {
            dist[node] = candidate;
            pushOrDecrease(node);
        }
    }

    public static void main(String[] args) throws Exception {
